select `ni`.`nin_id_planilla` AS `nin_id_planilla`,`p`.`ppl_numero` AS `planilla`,`p`.`ppl_estado_proceso` AS `estado_planilla`,`e`.`emp_correlativo` AS `id_empleado`,`e`.`emp_dpi` AS `emp_dpi`,concat(`e`.`emp_nombres`,' ',`e`.`emp_apellidos`) AS `nombre_completo`,`e`.`emp_fecha_ingreso` AS `emp_fecha_ingreso`,`e`.`emp_profesion_oficio` AS `puesto`,`ti`.`tin_tipo_ingreso` AS `tipo_ingreso`,`ni`.`nin_valor_teorico` AS `salario_teorico`,`ni`.`nin_porcentaje_aplicado` AS `porcentaje`,`ni`.`nin_dias_trabajados` AS `dias_trabajados`,`ni`.`nin_valor` AS `valor_ingreso` from (((`apps_rpjepq`.`rpj_prc_nomina_ingreso` `ni` join `apps_rpjepq`.`rpj_cat_parametro_planilla` `p` on(`p`.`ppl_correlativo` = `ni`.`nin_id_planilla`)) join `apps_rpjepq`.`rpj_mnt_empleado` `e` on(`e`.`emp_correlativo` = `ni`.`nin_id_empleado`)) join `apps_rpjepq`.`rpj_cat_tipo_ingreso` `ti` on(`ti`.`tin_id` = `ni`.`nin_tipo_ingreso`)) where `ni`.`nin_tipo_manejo` = 1
